def parse_time(value: object) -> datetime | None:
    try:
        parsed = datetime.fromisoformat(str(value).replace('Z', '+00:00'))
    except (TypeError, ValueError):
        return None
    return parsed.astimezone(timezone.utc) if parsed.tzinfo is not None else None

def utc_now() -> datetime:
    return datetime.now(timezone.utc)

def validate_browser_evidence(browser: dict[str, object], *, invocation_id: str, task_id: str, review_id: str, deployment: dict[str, object]) -> dict[str, bool]:
    started = parse_time(browser.get('started_at_utc'))
    completed = parse_time(browser.get('captured_at_utc'))
    health_verified = parse_time(deployment.get('health_verified_at'))
